UPDATE AI_PLAN SET CONFIRMED_YN = 'Y'
 WHERE CAMPAIGN_ID = #{campaignId}
   AND VERSION_NO = (SELECT MAX(VERSION_NO) FROM AI_PLAN WHERE CAMPAIGN_ID = #{campaignId})

UPDATE DRAFT SET COPY_TEXT = #{copyText}, IMAGE_URL = #{imageUrl}, SELECTED_YN = ${selected ? "'Y'" : "'N'"},
       UPDATED_AT = SYSDATE
 WHERE DRAFT_ID = #{draftId}
